                            format!("tag value must be a string of at most {MAX_VALUE_BYTES} bytes"),
                        )
                    })?;
                Ok((TagKey::parse(key)?, value.to_owned()))
            })
            .collect::<Result<_>>()
            .map(Self)
    }
}

